function parseLedger(markdown) {
  const lines = markdown.split('\n');
  // Find the authoritative "## Transaction Ledger" section using regex anchored to line start
  let startIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (/^## Transaction Ledger$/.test(lines[i])) {
      startIdx = i;
    }
  }
  if (startIdx < 0) return [];

  // Find the end of this section (next ## heading or EOF)
  let endIdx = lines.length;
  for (let i = startIdx + 1; i < lines.length; i++) {
    if (/^## /.test(lines[i])) {
      endIdx = i;
      break;
    }
  }

  const sectionLines = lines.slice(startIdx, endIdx);
  const section = sectionLines.join('\n');

  // Parse blocks split by ### headings
  const blocks = section.split(/^### /m).slice(1);
  const byId = new Map();

  for (const block of blocks) {
    const blockLines = block.split('\n');
    const transactionId = blockLines[0].trim();
    if (!transactionId.startsWith('TXN-')) continue;

    // Check for provisional: true
    let isProvisional = false;
    const row = { transaction_id: transactionId };
    for (const line of blockLines) {
      const trimmed = line.trim();
      if (/^provisional:\s*true$/i.test(trimmed)) {
        isProvisional = true;
      }
      if (trimmed.startsWith('amount:')) {
        row.amount = Number(trimmed.slice(7).trim());
      } else if (trimmed.startsWith('owner:')) {
        row.owner = trimmed.slice(6).trim();
      } else if (trimmed.startsWith('status:')) {
        row.status = trimmed.slice(7).trim();
      } else if (trimmed.startsWith('date:')) {
        row.date = trimmed.slice(5).trim();
      }
    }

    if (isProvisional) continue;

    // Last non-provisional block wins
    byId.set(transactionId, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
