const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function reconcileTransactions(parsed) {
  // Step 1: Load ledger base rows
  const byId = new Map();
  for (const row of parsed.ledger) {
    byId.set(row.transaction_id, {
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: row.status ? row.status.toLowerCase() : 'pending',
      date: row.date,
      amount: row.amount,
    });
  }

  // Step 2: Apply meeting amendments (Brief 05)
  // Only when signed: true AND (no effective or effective >= ledger date)
  for (const meeting of parsed.meetings) {
    const target = byId.get(meeting.transaction_id);
    if (!target) continue;
    if (!meeting.signed) continue;
    if (meeting.effective) {
      if (meeting.effective < target.date) continue;
    }
    target.owner = meeting.owner;
  }

  // Step 3: Apply compliance emails (Brief 02, 03)
  // Only compliance@ senders, status precedence (only upgrade), sent >= ledger date if sent line present
  for (const email of parsed.emails) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;
    const newStatus = email.status;
    const oldOrder = STATUS_ORDER[target.status] !== undefined ? STATUS_ORDER[target.status] : -1;
    const newOrder = STATUS_ORDER[newStatus] !== undefined ? STATUS_ORDER[newStatus] : -1;
    if (newOrder <= oldOrder) continue; // only upgrade
    // Brief 03: check sent date
    if (email.sent) {
      if (email.sent < target.date) continue;
    }
    target.status = newStatus;
  }

  // Save pre-correction state for compliance_hold (Brief 09)
  const preCorrectionState = new Map();
  for (const [id, row] of byId) {
    preCorrectionState.set(id, { ...row });
  }

  // Step 4: Apply corrections (Brief 04)
  // For each (txn, field), pick notice with greatest effective date
  // Group corrections by (transaction_id, field)
  const corrGroups = new Map();
  for (const notice of parsed.corrections) {
    const key = `${notice.transaction_id}||${notice.field}`;
    if (!corrGroups.has(key)) corrGroups.set(key, []);
    corrGroups.get(key).push(notice);
  }

  const report = [];
  const statusCorrectionWinners = new Set(); // track txns with winning status corrections

  for (const [key, notices] of corrGroups) {
    // Pick winner: greatest effective date lexicographically
    notices.sort((a, b) => (a.effective > b.effective ? -1 : a.effective < b.effective ? 1 : 0));
    const winner = notices[0];
    const target = byId.get(winner.transaction_id);
    if (!target) continue;

    // previous_value is field value before this correction
    let previousValue;
    if (winner.field === 'owner') {
      previousValue = target.owner;
      target.owner = winner.value;
    } else if (winner.field === 'status') {
      previousValue = target.status;
      target.status = winner.value.toLowerCase();
      statusCorrectionWinners.add(winner.transaction_id);
    } else if (winner.field === 'date') {
      previousValue = target.date;
      target.date = winner.value;
    } else {
      previousValue = '';
    }

    report.push({
      notice_id: winner.notice_id,
      transaction_id: winner.transaction_id,
      field: winner.field,
      previous_value: previousValue || '',
      new_value: winner.value,
      effective: winner.effective,
    });
  }

  // Sort report by notice_id ascending
  report.sort((a, b) => (a.notice_id < b.notice_id ? -1 : a.notice_id > b.notice_id ? 1 : 0));

  // Step 5: Compute effective_date (Brief 06)
  // If a winning correction modified 'date' or 'status', use that correction's effective
  // as effective_date. Otherwise keep ledger date.
  const corrEffective = new Map();
  for (const r of report) {
    if (r.field === 'date' || r.field === 'status') {
      const existing = corrEffective.get(r.transaction_id);
      if (!existing || r.effective > existing) {
        corrEffective.set(r.transaction_id, r.effective);
      }
    }
  }

  // Step 6: Build exception flags (Brief 07, 08, 09)
  // Build lookup for compliance emails with sent line per transaction
  const complianceEmailsByTxn = new Map();
  for (const email of parsed.emails) {
    if (!complianceEmailsByTxn.has(email.transaction_id)) {
      complianceEmailsByTxn.set(email.transaction_id, []);
    }
    complianceEmailsByTxn.get(email.transaction_id).push(email);
  }

  // Build policy exception lookup
  const policyByTxn = new Map();
  for (const pe of parsed.policyExceptions) {
    if (!policyByTxn.has(pe.transaction_id)) {
      policyByTxn.set(pe.transaction_id, []);
    }
    policyByTxn.get(pe.transaction_id).push(pe);
  }

  const items = sortByTransactionId(
    [...byId.values()].map((row) => {
      const effectiveDate = corrEffective.has(row.transaction_id)
        ? corrEffective.get(row.transaction_id)
        : (preCorrectionState.get(row.transaction_id) || row).date;
      const amount = Number(row.amount);
      const flags = [];

      // compliance_hold (Brief 07 + 09): final status is rejected,
      // qualifying compliance@ email with sent line,
      // compare sent against pre-correction date
      if (row.status === 'rejected') {
        const emails = complianceEmailsByTxn.get(row.transaction_id) || [];
        const preDate = preCorrectionState.get(row.transaction_id).date;
        for (const em of emails) {
          if (em.sent && em.sent >= preDate) {
            flags.push('compliance_hold');
            break;
          }
        }
      }

      // over_limit (Brief 07): amount > 10000
      if (amount > 10000) {
        flags.push('over_limit');
      }

      // policy_waiver (Brief 08): final status approved, amount > 10000,
      // policy exception with approved_by: compliance
      if (row.status === 'approved' && amount > 10000) {
        const policies = policyByTxn.get(row.transaction_id) || [];
        for (const p of policies) {
          if (p.approved_by === 'compliance') {
            flags.push('policy_waiver');
            break;
          }
        }
      }

      // retroactive_review (Brief 08): final status reversed, amount > 5000,
      // winning correction changed status
      if (row.status === 'reversed' && amount > 5000 && statusCorrectionWinners.has(row.transaction_id)) {
        flags.push('retroactive_review');
      }

      // Sort flags lexically and join with semicolon
      flags.sort();
      const exceptionReason = flags.length > 0 ? flags.join(';') : null;

      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status: row.status,
        effective_date: effectiveDate,
        amount_usd: Math.round(amount * 100) / 100,
        exception_reason: exceptionReason,
      };
    })
  );

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
